<section class="card review-panel"><h2>Listing content</h2><p><strong><?= esc(customer_listing_purpose($record)) ?> &mdash; PKR <?= number_format((float)$record['asking_price']) ?><?= $record['listing_purpose']==='rent'?' / month':'' ?></strong> &middot; <?= !empty($payload['negotiable'])?'Negotiable':'Not negotiable' ?></p><p class="review-description"><?= nl2br(esc($payload['description']??'')) ?></p><?php if($record['listing_purpose']==='rent'): ?><dl class="review-facts"><?php foreach(['security_deposit'=>'Security Deposit','advance_rent'=>'Advance Rent','furnishing'=>'Furnishing','lease_duration_months'=>'Lease Duration']as$key=>$label):$value=$payload['rental'][$key]??null; ?><div><dt><?= $label ?></dt><dd><?= $value===null?'Not provided':(in_array($key,['security_deposit','advance_rent'],true)?'PKR '.number_format((float)$value):esc($key==='lease_duration_months'?$value.' months':ucwords(str_replace('_',' ',(string)$value)))) ?></dd></div><?php endforeach ?></dl><?php endif ?><p>Submitted <?= esc(customer_date($payload['submitted_at']??$record['created_at'])) ?></p><?php if(!empty($payload['review_note'])): ?><h3>Current review feedback</h3><p class="alert alert-warning"><?= nl2br(esc($payload['review_note'])) ?></p><?php endif ?></section>
<section class="card review-panel"><h2>Final photo set</h2><p>First photo is the cover. Save any photo changes before making a decision. Removed files remain stored for history.</p><p class="alert alert-warning" data-photo-dirty hidden>Unsaved photo changes. Save or reload before approval.</p><ol class="review-photo-grid" data-review-photos><?php foreach($photos as$i=>$photo): ?><li data-review-photo data-photo-id="<?= esc($photo['id']??'','attr') ?>"><?php if($photo['valid']): ?><a href="<?= esc($photo['url'],'attr') ?>" target="_blank" rel="noopener"><img src="<?= esc($photo['url'],'attr') ?>" alt="Listing photo <?= $i+1 ?>"></a><?php else: ?><p class="alert alert-warning">Photo unavailable or altered. Remove/replace before approval.</p><?php endif ?><span>Photo <?= $i+1 ?></span><?php if($reviewable&&can('resale_listings.edit')): ?><div class="d-flex flex-wrap gap-1"><button type="button" class="btn btn-sm btn-outline-secondary" data-photo-move="cover">Make cover</button><button type="button" class="btn btn-sm btn-outline-secondary" data-photo-move="up">Up</button><button type="button" class="btn btn-sm btn-outline-secondary" data-photo-move="down">Down</button><button type="button" class="btn btn-sm btn-outline-danger" data-photo-remove>Remove</button></div><?php endif ?></li><?php endforeach ?></ol><?php if(!$photos): ?><p>No uploaded photos. A generic property placeholder is used until photos are added.</p><?php endif ?>
