<?php else: ?><p>This record is not awaiting a review decision. No approval/reopening action is available.</p><?php endif ?><?php if($public['public_visible']??false): ?><a class="btn btn-outline-secondary" href="<?= esc(admin_legacy_url('listing.php').'?id='.$id,'attr') ?>" target="_blank" rel="noopener">View Public Listing</a><?php endif ?></section></aside></div>
